/**
 * Material Design 3 Morph curves and interpolation engine for Synapse mobile loader.
 * Derived from official curves: ../synapse-onboarding-motion-prototype/public/assets/synapse/md3-morphs.json
 * Seven shapes, 650ms per morph stage, stiffness 200, damping ratio 0.6.
 */

export type CubicCurve = [number, number, number, number, number, number, number, number];

export interface MorphPair {
  readonly from: readonly CubicCurve[];
  readonly to: readonly CubicCurve[];
}

export const MD3_SHAPE_COUNT = 7;
export const MD3_STAGE_DURATION_MS = 650;
export const MD3_TOTAL_CYCLE_MS = MD3_SHAPE_COUNT * MD3_STAGE_DURATION_MS; // 4550ms

/**
 * Analytical spring response for second-order underdamped system:
 * stiffness = 200, damping ratio (zeta) = 0.6.
 * Normalized duration T = 0.65s (650ms).
 * omega_0 = sqrt(200) ≈ 14.1421356
 * omega_d = omega_0 * sqrt(1 - zeta^2) = omega_0 * 0.8 ≈ 11.3137085
 * decay = exp(-zeta * omega_0 * t) = exp(-0.6 * sqrt(200) * (f * 0.65))
 * response = 1 - decay * (cos(omega_d * t) + (zeta / sqrt(1 - zeta^2)) * sin(omega_d * t))
 * where zeta / sqrt(1 - zeta^2) = 0.6 / 0.8 = 0.75
 */
export function md3SpringResponse(f: number): number {
  'worklet';
  if (f <= 0) return 0;
  if (f >= 1) return 1;
  const t = f * 0.65;
  const omega0 = 14.14213562373095; // Math.sqrt(200)
  const decay = Math.exp(-0.6 * omega0 * t);
  const arg = omega0 * 0.8 * t;
  return 1 - decay * (Math.cos(arg) + 0.75 * Math.sin(arg));
}

export function md3RotationDegrees(base: number, f: number, spring: number): number {
  'worklet';
  return 140 * base + 50 * f + 90 * spring;
}

