/**
 * Linear mix between two numbers
 */
function mix(a: number, b: number, t: number): number {
  'worklet';
  return a + (b - a) * t;
}

/**
 * Computes SVG path string for a given morph stage index and spring interpolation factor.
 */
export function computeMd3Path(base: number, springProgress: number): string {
  'worklet';
  const pairIndex = ((base % MD3_SHAPE_COUNT) + MD3_SHAPE_COUNT) % MD3_SHAPE_COUNT;
  const pair = MD3_MORPH_PAIRS[pairIndex];
  if (!pair) return '';
  const from = pair.from;
  const to = pair.to;
  const count = from.length;
  if (count === 0) return '';

  const firstFrom = from[0];
  const firstTo = to[0];
  const startX = mix(firstFrom[0], firstTo[0], springProgress) * 100;
  const startY = mix(firstFrom[1], firstTo[1], springProgress) * 100;

  let d = 'M ' + startX.toFixed(3) + ' ' + startY.toFixed(3);
  for (let i = 0; i < count; i++) {
    const cf = from[i];
    const ct = to[i];
    const cp1x = mix(cf[2], ct[2], springProgress) * 100;
    const cp1y = mix(cf[3], ct[3], springProgress) * 100;
    const cp2x = mix(cf[4], ct[4], springProgress) * 100;
    const cp2y = mix(cf[5], ct[5], springProgress) * 100;
    const endX = mix(cf[6], ct[6], springProgress) * 100;
    const endY = mix(cf[7], ct[7], springProgress) * 100;
    d += ' C ' + cp1x.toFixed(3) + ' ' + cp1y.toFixed(3) + ' ' + cp2x.toFixed(3) + ' ' + cp2y.toFixed(3) + ' ' + endX.toFixed(3) + ' ' + endY.toFixed(3);
  }
  return d + ' Z';
}

/**
 * Computes both path and rotation for a normalized cycle progress (where 1 cycle = 7 shapes = 4550ms).
 * sequence = cycleTime / 650ms.
 */
export function evaluateMd3Loader(sequence: number): { path: string; rotation: number; base: number; f: number; spring: number } {
  'worklet';
  const base = Math.floor(sequence);
  const f = sequence - base;
  const spring = md3SpringResponse(f);
  const path = computeMd3Path(base, spring);
  const rotation = md3RotationDegrees(base, f, spring);
  return { path, rotation, base, f, spring };
}
